        dados = json.loads(caminho.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return {k: v for k, v in dados.items() if _validar(v)} if isinstance(dados, dict) else {}


def _gravar_cache(caminho: Path | None, dados: dict[str, dict]) -> None:
    if caminho is None or not dados:
        return
    caminho.parent.mkdir(parents=True, exist_ok=True)
    caminho.write_text(json.dumps(dados, ensure_ascii=False, indent=1, sort_keys=True), encoding="utf-8")


def _cliente_anthropic(cfg: dict) -> Cliente | None:
    """Cliente real (SDK `anthropic`, import tardio). Sem o pacote, None: fica o texto padrão."""
    try:
        import anthropic
    except ImportError:
        print("Aviso: pacote anthropic não instalado; motivos sem regra ficam com o texto padrão.")
        return None
    api = anthropic.Anthropic(timeout=float(cfg["timeout_s"]), max_retries=1)

    def chamar(sistema: str, usuario: str) -> dict:
        pedido = {
            "model": cfg["modelo"], "max_tokens": 4000, "system": sistema,
            "messages": [{"role": "user", "content": usuario}],
            "output_config": {"effort": cfg["esforco"],
                              "format": {"type": "json_schema", "schema": ESQUEMA_RESPOSTA}},
        }
        if cfg.get("fallbacks") and cfg.get("beta_fallbacks"):
            resposta = api.beta.messages.create(**pedido, betas=[cfg["beta_fallbacks"]],
                                                fallbacks=cfg["fallbacks"])
        else:
            resposta = api.messages.create(**pedido)
        if resposta.stop_reason != "end_turn":
            raise RuntimeError(f"resposta interrompida ({resposta.stop_reason})")
        return json.loads(next(b.text for b in resposta.content if b.type == "text"))

    return chamar

