input.content:
"""Motivos de pendência escritos por LLM, só para o que as regras não sabem explicar (nível Extra).

Quase toda pendência sai com motivo escrito por regra. Três casos ficam com texto genérico e são
marcados com `motivo_mapeado = False`: lançamento bancário sem padrão em `bancos.regras`, tipo de
lançamento novo na Orbe e tipo de pendência fora do catálogo `pendencias.tipos`. Só para esses,
`completar_motivos` pede à LLM:
- `explicacao`: o que a linha provavelmente é, sem datas nem valores (esses fatos continuam vindo da
  regra; a explicação é acrescentada ao motivo original, marcada como leitura da IA);
- `sugestao`: o próximo passo;
- `quem_decide`: usado só quando o tipo não está no catálogo (no catálogo, a decisão já está tomada).

A LLM não muda valor, origem, tipo nem bloqueio. Sem chave, sem rede, resposta inválida ou recusa:
o texto padrão é mantido e a pendência sai com `origem_motivo = PADRAO`. Casos iguais (mesmo tipo e
mesma descrição) geram uma chamada só, e a resposta fica em cache para a reexecução do mês.
Toda a configuração (modelo, prompt, limites) fica em `config/regras.yaml`, seção `ia`.
"""
from __future__ import annotations

import json
from collections.abc import Callable
from pathlib import Path

from src.core.contratos import PendenciaCalculada
from src.core.saida import QUEM_DECIDE
from src.regras.classificacao import normalizar_descricao

# (prompt de sistema, mensagem do usuário) -> {"explicacao", "sugestao", "quem_decide"}
Cliente = Callable[[str, str], dict]

ESQUEMA_RESPOSTA = {
    "type": "object",
    "properties": {
        "explicacao": {"type": "string"},
        "sugestao": {"type": "string"},
        "quem_decide": {"type": "string", "enum": list(QUEM_DECIDE)},
    },
    "required": ["explicacao", "sugestao", "quem_decide"],
    "additionalProperties": False,
}
_OBRIGATORIAS = ("modelo", "prompt_motivo", "sugestao_fallback", "rotulo_ia")


def ia_ativa(regras: dict) -> bool:
    return bool(((regras or {}).get("ia") or {}).get("ativo"))


def configuracao(regras: dict) -> dict:
    cfg = (regras or {}).get("ia") or {}
    faltando = [c for c in _OBRIGATORIAS if not str(cfg.get(c) or "").strip()]
    if faltando:
        raise ValueError(f"ia: {', '.join(faltando)} obrigatório(s) quando ia.ativo = true")
    return {"timeout_s": 30, "max_chamadas": 20, "esforco": "low", **cfg}


def completar_motivos(pendencias: list[PendenciaCalculada], regras: dict, cliente: Cliente | None = None,
                      cache: Path | None = None) -> list[PendenciaCalculada]:
    """Devolve as pendências com `origem_motivo`; reescreve só as de `motivo_mapeado = False`."""
    sem_regra = [p for p in pendencias if p.get("motivo_mapeado") is False]
    if not sem_regra or not ia_ativa(regras):
        return [{**p, "origem_motivo": "PADRAO" if p.get("motivo_mapeado") is False else "REGRA"}
                for p in pendencias]

    cfg = configuracao(regras)
    catalogo = set(((regras.get("pendencias") or {}).get("tipos") or {}))
    exemplos = _exemplos(pendencias)
    guardadas = _ler_cache(cache)
    chamar = cliente or _cliente_anthropic(cfg)
    respostas: dict[str, dict | None] = {}
    chamadas = 0
    for p in sem_regra:
        chave = _chave(p)
        if chave in respostas:
            continue
        resposta = guardadas.get(chave)
        if resposta is None and chamar is not None and chamadas < int(cfg["max_chamadas"]):
            chamadas += 1
            try:
                resposta = _validar(chamar(cfg["prompt_motivo"], _mensagem(p, exemplos)))
            except Exception as erro:  # rede, chave, recusa: o fechamento segue com o texto padrão
                print(f"Aviso: IA indisponível para motivos de pendência ({type(erro).__name__}: {erro}); "
                      "mantido o texto padrão.")
                chamar = None
            if resposta is not None:
                guardadas[chave] = resposta
        respostas[chave] = resposta
    _gravar_cache(cache, guardadas)

    completadas: list[PendenciaCalculada] = []
    for p in pendencias:
        if p.get("motivo_mapeado") is not False:
            completadas.append({**p, "origem_motivo": "REGRA"})
            continue
        resposta = respostas.get(_chave(p))
        if resposta is None:
            completadas.append({**p, "origem_motivo": "PADRAO"})
            continue
        completadas.append({
            **p,
            "motivo": f"{p['motivo']} {cfg['rotulo_ia']} {resposta['explicacao']}",
            "sugestao": resposta["sugestao"],
            "quem_decide": p["quem_decide"] if p["tipo"] in catalogo else resposta["quem_decide"],
            "origem_motivo": "IA",
        })
    return completadas


def _chave(p: PendenciaCalculada) -> str:
    ctx = p.get("contexto_ia") or {}
    padrao = ctx.get("descricao") or ctx.get("tipo_lancamento") or p["motivo"]
    return f"{p['tipo']}|{ctx.get('origem', '')}|{normalizar_descricao(padrao)}"


def _exemplos(pendencias: list[PendenciaCalculada]) -> list[dict[str, str]]:
    """Um motivo escrito por regra de cada tipo (até 3), para a LLM seguir o tom."""
    vistos: dict[str, dict[str, str]] = {}
    for p in pendencias:
        if p.get("motivo_mapeado") is not False and p["tipo"] not in vistos and len(vistos) < 3:
            vistos[p["tipo"]] = {"tipo": p["tipo"], "motivo": p["motivo"], "sugestao": p.get("sugestao", "")}
    return list(vistos.values())


def _mensagem(p: PendenciaCalculada, exemplos: list[dict[str, str]]) -> str:
    return json.dumps({
        "pendencia": {"tipo": p["tipo"], "motivo_atual": p["motivo"], "quem_decide_atual": p["quem_decide"],
                      "dados_da_linha": p.get("contexto_ia") or {"ref_origem": p["ref_origem"]}},
        "quem_pode_decidir": list(QUEM_DECIDE),
        "exemplos_de_outras_pendencias": exemplos,
    }, ensure_ascii=False, indent=1)


def _validar(resposta) -> dict | None:
    if not isinstance(resposta, dict):
        return None
    textos = {c: str(resposta.get(c) or "").strip() for c in ("explicacao", "sugestao")}
    if not all(textos.values()) or resposta.get("quem_decide") not in QUEM_DECIDE:
        return None
    return {**textos, "quem_decide": resposta["quem_decide"]}


def _ler_cache(caminho: Path | None) -> dict[str, dict]:
    if caminho is None or not caminho.exists():
        return {}
    try:
        dados = json.loads(caminho.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    return {k: v for k, v in dados.items() if _validar(v)} if isinstance(dados, dict) else {}


def _gravar_cache(caminho: Path | None, dados: dict[str, dict]) -> None:
    if caminho is None or not dados:
        return
    caminho.parent.mkdir(parents=True, exist_ok=True)
    caminho.write_text(json.dumps(dados, ensure_ascii=False, indent=1, sort_keys=True), encoding="utf-8")


def _cliente_anthropic(cfg: dict) -> Cliente | None:
    """Cliente real (SDK `anthropic`, import tardio). Sem o pacote, None: fica o texto padrão."""
    try:
        import anthropic
    except ImportError:
        print("Aviso: pacote anthropic não instalado; motivos sem regra ficam com o texto padrão.")
        return None
    api = anthropic.Anthropic(timeout=float(cfg["timeout_s"]), max_retries=1)

    def chamar(sistema: str, usuario: str) -> dict:
        pedido = {
            "model": cfg["modelo"], "max_tokens": 4000, "system": sistema,
            "messages": [{"role": "user", "content": usuario}],
            "output_config": {"effort": cfg["esforco"],
                              "format": {"type": "json_schema", "schema": ESQUEMA_RESPOSTA}},
        }
        if cfg.get("fallbacks") and cfg.get("beta_fallbacks"):
            resposta = api.beta.messages.create(**pedido, betas=[cfg["beta_fallbacks"]],
                                                fallbacks=cfg["fallbacks"])
        else:
            resposta = api.messages.create(**pedido)
        if resposta.stop_reason != "end_turn":
            raise RuntimeError(f"resposta interrompida ({resposta.stop_reason})")
        return json.loads(next(b.text for b in resposta.content if b.type == "text"))

    return chamar

